log.raw:
{
  "understanding": {
    "purpose": "예금 상품의 금리와 가입 조건을 비교하고 각 상품의 특징을 살펴보는 표입니다.",
    "reading": "독자는 상품명을 기준으로 행을 따라 읽고, 금리·가입 기간·최소 금액을 세로로 비교한 뒤 특징을 확인합니다. 긴 특징이 만드는 행 높이는 같은 행의 다른 셀 줄바꿈을 수용할 수 있습니다.",
    "groups": [
      "금리(연), 가입 기간, 최소 금액은 상품 선택에 필요한 비교 조건으로 함께 읽힙니다.",
      "상품명은 각 비교 행의 식별자이고, 특징은 해당 상품에 대한 설명입니다."
    ],
    "keep_intact": [
      "상품명은 가능한 한 온전하게 유지",
      "금리의 숫자, 소수점, 퍼센트 기호와 범위",
      "가입 기간의 숫자와 단위",
      "최소 금액의 숫자와 통화 단위"
    ],
    "may_wrap": [
      "특징의 긴 설명은 자연스러운 어절 경계에서 줄바꿈",
      "기본 금리와 우대 금리처럼 구분되는 조건 사이의 줄바꿈",
      "여러 가입 기간은 항목 사이에서 줄바꿈"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [118, 108, 90, 80, 142],
      "idea": "상품명을 한 줄로 유지하고 비교 조건에 충분한 폭을 준 뒤 나머지를 특징에 배분하는 균형형입니다."
    },
    {
      "name": "B",
      "widths": [100, 108, 75, 75, 180],
      "idea": "상품명과 일부 조건의 줄바꿈을 허용해 긴 특징 설명에 더 많은 공간을 주는 설명 중심형입니다."
    },
    {
      "name": "C",
      "widths": [118, 145, 115, 92, 68],
      "idea": "금리와 가입 조건을 넓게 배치해 세로 비교를 쉽게 하고 특징은 좁은 설명란에서 길게 줄바꿈하는 비교 중심형입니다."
    }
  ]
}
